// ServerInterface represents all server handlers.
type ServerInterface interface {
	// GetAccount Current account
	// (GET /account)
	GetAccount(c *gin.Context)
	// UpdateAccount Update visible name and phone
	// (PATCH /account)
	UpdateAccount(c *gin.Context)
	// DeactivateAccount Deactivate own account
	// (POST /account/deactivate)
	DeactivateAccount(c *gin.Context)
	// StartGoogleAuth Start Google sign-in
	// (GET /auth/google)
	StartGoogleAuth(c *gin.Context)
	// GoogleCallback Google OAuth callback
	// (GET /auth/google/callback)
	GoogleCallback(c *gin.Context)
	// Logout End the current session
	// (POST /auth/logout)
	Logout(c *gin.Context)
	// ListCategories Listing categories (config)
	// (GET /catalog/categories)
	ListCategories(c *gin.Context)
	// SearchCatalog Public search (no login required)
	// (GET /catalog/listings)
	SearchCatalog(c *gin.Context, params SearchCatalogParams)
	// GetPublicListing Public ficha (no login required)
	// (GET /catalog/listings/{id})
	GetPublicListing(c *gin.Context, id openapi_types.UUID)
	// GetPublicCalendar Public calendar (no login required)
	// (GET /catalog/listings/{id}/calendar)
	GetPublicCalendar(c *gin.Context, id openapi_types.UUID, params GetPublicCalendarParams)
	// StaffResolveDamage Staff resolution of a contested claim (final in v1)
	// (POST /damage/{id}/resolve)
	StaffResolveDamage(c *gin.Context, id openapi_types.UUID)
	// RespondDamageClaim Renter response to an open claim (48h window)
	// (POST /damage/{id}/respond)
	RespondDamageClaim(c *gin.Context, id openapi_types.UUID)
	// ForgiveDebt Forgive a debt (staff; reason mandatory)
	// (POST /debt/{id}/forgive)
	ForgiveDebt(c *gin.Context, id openapi_types.UUID)
	// SettleDebt Mark a debt as paid (renter)
	// (POST /debt/{id}/settle)
	SettleDebt(c *gin.Context, id openapi_types.UUID)
	// Healthz Liveness probe
	// (GET /healthz)
	Healthz(c *gin.Context)
	// ListMineListings List the caller's listings
	// (GET /listings)
	ListMineListings(c *gin.Context)
	// CreateListingDraft Create a draft listing
	// (POST /listings)
	CreateListingDraft(c *gin.Context)
	// GetMyListing Get one of the caller's listings (private)
	// (GET /listings/{id})
	GetMyListing(c *gin.Context, id openapi_types.UUID)
	// UpdateListing Update a draft or paused listing
	// (PATCH /listings/{id})
	UpdateListing(c *gin.Context, id openapi_types.UUID)
	// ListBlocks Owner view of availability blocks
	// (GET /listings/{id}/blocks)
	ListBlocks(c *gin.Context, id openapi_types.UUID)
	// AddBlock Add an availability block
	// (POST /listings/{id}/blocks)
	AddBlock(c *gin.Context, id openapi_types.UUID)
	// RemoveBlock Remove an availability block
	// (DELETE /listings/{id}/blocks/{blockId})
	RemoveBlock(c *gin.Context, id openapi_types.UUID, blockId openapi_types.UUID)
	// PauseListing Pause a published listing
	// (POST /listings/{id}/pause)
	PauseListing(c *gin.Context, id openapi_types.UUID)
	// PublishListing Publish (or unpause) a listing
	// (POST /listings/{id}/publish)
	PublishListing(c *gin.Context, id openapi_types.UUID)
	// GetOwnerOnboarding Owner onboarding state
	// (GET /owner/onboarding)
	GetOwnerOnboarding(c *gin.Context)
	// UpdateOwnerOnboarding Update payout details and/or accept terms
	// (PATCH /owner/onboarding)
	UpdateOwnerOnboarding(c *gin.Context)
	// PaymentWebhook PSP webhook (signature verified server-side)
	// (POST /payments/webhook)
	PaymentWebhook(c *gin.Context, params PaymentWebhookParams)
	// Readyz Readiness probe
	// (GET /readyz)
	Readyz(c *gin.Context)
	// ListMyRentals List the caller's rentals
	// (GET /rentals)
	ListMyRentals(c *gin.Context)
	// CreateRental Create a reservation intent (tenant)
	// (POST /rentals)
	CreateRental(c *gin.Context)
	// GetRental Get one rental
	// (GET /rentals/{id})
	GetRental(c *gin.Context, id openapi_types.UUID)
	// AcceptRental Accept the rental (owner)
	// (POST /rentals/{id}/accept)
	AcceptRental(c *gin.Context, id openapi_types.UUID)
	// AuthorizeRentalPayment Authorize payment (tenant)
	// (POST /rentals/{id}/authorize)
	AuthorizeRentalPayment(c *gin.Context, id openapi_types.UUID)
	// CancelRental Cancel the rental pre-acceptance (tenant)
	// (POST /rentals/{id}/cancel)
	CancelRental(c *gin.Context, id openapi_types.UUID)
	// GetRentalCancellation Get the cancellation record (immutable, both parties)
	// (GET /rentals/{id}/cancellations)
	GetRentalCancellation(c *gin.Context, id openapi_types.UUID)
	// CreateRentalCancellation Cancel a rental (tenant, owner, or platform)
	// (POST /rentals/{id}/cancellations)
	CreateRentalCancellation(c *gin.Context, id openapi_types.UUID)
	// OpenDamageClaim Open a damage claim for the rental (owner, 48h window)
	// (POST /rentals/{id}/damage)
	OpenDamageClaim(c *gin.Context, id openapi_types.UUID)
	// DeclineRental Decline the rental (owner)
	// (POST /rentals/{id}/decline)
	DeclineRental(c *gin.Context, id openapi_types.UUID)
	// RegisterRentalPickup Register pickup state (either party)
	// (POST /rentals/{id}/pickup)
	RegisterRentalPickup(c *gin.Context, id openapi_types.UUID)
	// GetRentalReceipt Tenant receipt (immutable)
	// (GET /rentals/{id}/receipt)
	GetRentalReceipt(c *gin.Context, id openapi_types.UUID)
	// RegisterRentalReturn Register return state and close the rental (either party)
	// (POST /rentals/{id}/return)
	RegisterRentalReturn(c *gin.Context, id openapi_types.UUID)
}

// ServerInterfaceWrapper converts contexts to parameters.
type ServerInterfaceWrapper struct {
	Handler            ServerInterface
	HandlerMiddlewares []MiddlewareFunc
	ErrorHandler       func(*gin.Context, error, int)
}

type MiddlewareFunc func(c *gin.Context)

// GetAccount operation middleware
func (siw *ServerInterfaceWrapper) GetAccount(c *gin.Context) {

	for _, middleware := range siw.HandlerMiddlewares {
		middleware(c)
		if c.IsAborted() {
			return
		}
	}

	siw.Handler.GetAccount(c)
}

